insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_138'
from (values
('127.888.d.9.A',3,'A student inspects the cowling, wheel fairings and control cables on a trainer, following the Part 43 100-hour checklist. She is:','["performing a portion of a 100-hour inspection in accordance with 14 CFR Part 43", "painting the airplane", "fueling the airplane", "skipping an inspection"]'::jsonb,0,'100-hour inspection.','original'),
('127.888.d.9.A',4,'A 100-hour inspection is required for aircraft that are:','["never flown", "used to carry persons for hire or for flight instruction for hire", "owned by retirees", "stored in a hangar"]'::jsonb,1,'Who needs 100-hour.','original'),
('127.888.d.9.B',3,'After the inspection, the mechanic writes that the aircraft is returned to service, or lists the defects that make it unairworthy. She is:','["hiding defects", "guessing at results", "entering the results of a 100-hour inspection, including airworthy and unairworthy conditions", "leaving no record"]'::jsonb,2,'Log the result.','original'),
('127.888.d.9.B',4,'If an inspection finds a defect that makes an aircraft unairworthy, the mechanic must:','["sign it as airworthy", "paint over it", "say nothing", "give the owner a signed, dated list of the discrepancies"]'::jsonb,3,'Discrepancy list.','original'),
('127.888.d.9.C',3,'A mechanic checks the aircraft''s records and equipment against AD and registration paperwork to confirm they comply. She is:','["analyzing and inspecting equipment and documents to determine compliance", "avoiding records", "ignoring documents", "only washing the plane"]'::jsonb,0,'Compliance check.','original'),
('127.888.d.9.C',4,'A required AD that has not been recorded as complied with means the aircraft:','["is lighter", "may not be airworthy until it is resolved", "is fine", "is faster"]'::jsonb,1,'AD status.','original'),
('127.888.d.10.A',3,'Before lifting a plane, Ravi checks the jack''s rating, uses a level floor and keeps people out from under the plane. He is identifying:','["shortcuts", "unsafe habits", "safety precautions when using aircraft jacks", "no precautions"]'::jsonb,2,'Jack safety.','original'),
('127.888.d.10.A',4,'Jacking an aircraft outdoors in strong wind is unsafe because it can:','["clean the jacks", "help balance", "speed lifting", "tip or shift the aircraft off the jacks"]'::jsonb,3,'Wind and jacks.','original'),
('127.888.d.10.B',3,'A mechanic wears eye protection and relieves system pressure before loosening a hydraulic line. She is identifying:','["safety precautions when working with high-pressure fluids and gases", "no precautions", "random steps", "shortcuts"]'::jsonb,0,'Pressure safety.','original'),
('127.888.d.10.B',4,'A pinhole leak in a high-pressure hydraulic line can inject fluid through the skin, so a mechanic should:','["hold a hand close", "never check for leaks with bare hands", "use bare fingers", "ignore it"]'::jsonb,1,'Injection hazard.','original'),
('127.888.d.10.C',3,'A shop keeps hydraulic fluid in closed, labeled containers away from heat and ignition. This shows:','["no labels", "unsafe storage", "safety precautions in the storage and handling of hydraulic fluid", "open containers"]'::jsonb,2,'Fluid storage.','original'),
('127.888.d.10.C',4,'Hydraulic fluid containers should be labeled and kept sealed to prevent:','["faster flow", "fluid improvements", "extra cleaning", "contamination and mix-ups between fluid types"]'::jsonb,3,'Labeling.','original'),
('127.888.d.10.D',3,'A mechanic puts gear safety pins in and keeps clear of the wheel wells during a retraction test. She is identifying:','["safety precautions for operating retractable landing gear", "skipping pins", "no precautions", "working under gear"]'::jsonb,0,'Retraction safety.','original'),
('127.888.d.10.D',4,'Ground lock pins are installed to prevent:','["fuel flowing", "the gear from retracting while personnel are working", "the gear extending", "tires wearing"]'::jsonb,1,'Gear pins.','original'),
('127.888.d.10.E',3,'Before removing a wheel, a mechanic chocks the other wheels, deflates the tire and uses a wheel dolly. She is identifying:','["unsafe steps", "no precautions", "safety precautions in landing gear, tire and wheel maintenance", "skipping chocks"]'::jsonb,2,'Wheel safety.','original'),
('127.888.d.10.E',4,'A tire should be deflated before wheel disassembly because trapped pressure can:','["soften the tire", "clean the rim", "cool the brake", "cause a violent explosion"]'::jsonb,3,'Tire explosion.','original'),
('127.888.d.10.F',3,'A student lists struts, trunnions, drag links and retraction actuators as parts of a retractable gear. She is describing:','["fixed and retractable landing gear systems and components", "propeller systems", "fuel systems", "oxygen systems"]'::jsonb,0,'Gear systems.','original'),
('127.888.d.10.F',4,'The main difference between fixed and retractable gear is that retractable gear:','["is always bigger", "folds into the airframe after takeoff", "has no tires", "never moves"]'::jsonb,1,'Retractable gear.','original'),
('127.888.d.10.G',3,'A mechanic checks the oleo strut for correct air pressure and fluid level and lubricates the pivot points. She is explaining:','["a random task", "an optional chore", "the necessity of landing gear strut servicing and lubrication", "no need for service"]'::jsonb,2,'Strut servicing.','original'),
('127.888.d.10.G',4,'An oleo strut that has lost its air or fluid will:','["reduce tire wear", "ride perfectly", "hold more weight", "bottom out and give a harsh ride and landing"]'::jsonb,3,'Underserviced strut.','original'),
('127.888.d.10.H',3,'A mechanic compares checking bungee cords for stretch and cracks with checking a spring steel leg for cracks and bends. She is:','["describing and comparing inspection methods for bungee and spring steel gear", "painting gear", "fueling the aircraft", "avoiding inspection"]'::jsonb,0,'Gear inspection types.','original'),
('127.888.d.10.H',4,'Spring steel landing gear is common on:','["large airliners", "light general aviation airplanes", "rockets", "helicopters only"]'::jsonb,1,'Spring steel gear.','original'),
('127.888.d.10.I',3,'A student compares castering nose wheels steered with differential braking and nose wheels steered through rudder pedals linked by rods or cables. She is:','["ignoring wheels", "guessing", "describing and comparing aircraft steering systems", "avoiding steering"]'::jsonb,2,'Steering systems.','original'),
('127.888.d.10.I',4,'A castering nose wheel is steered mainly by:','["a steering wheel only", "no input", "an electric motor only", "differential braking and rudder"]'::jsonb,3,'Castering.','original'),
('127.888.d.10.J',3,'A mechanic tests the gear-down lights, the position switches and the gear warning horn. She is explaining:','["landing gear position and warning system inspection, check and servicing", "a prop check", "a paint check", "a tire check"]'::jsonb,0,'Gear warning.','original'),
('127.888.d.10.J',4,'A gear warning horn sounds when the gear is not down and locked and the:','["cabin is hot", "throttle is reduced for landing", "door is open", "radio is on"]'::jsonb,1,'Gear horn logic.','original'),
('127.888.d.10.K',3,'A mechanic checks brake pads for wear, disc thickness and signs of overheating. She is explaining:','["gear retraction", "tire inflation", "brake assembly servicing and inspection", "wheel painting"]'::jsonb,2,'Brake inspection.','original'),
('127.888.d.10.K',4,'A brake disc worn below the manufacturer''s minimum thickness should be:','["ignored", "reused", "painted", "replaced"]'::jsonb,3,'Replace worn disc.','original'),
('127.888.d.10.L',3,'A student compares independent master cylinders on rudder pedals with a power boost system that uses system hydraulic pressure. She is:','["describing and comparing brake actuating systems", "describing engines", "describing oxygen", "describing fuel"]'::jsonb,0,'Brake actuation.','original'),
('127.888.d.10.L',4,'On many light airplanes, toe brakes are operated by:','["a voice command", "pushing the top of the rudder pedals", "pulling a handle only", "a foot pedal on the floor only"]'::jsonb,1,'Toe brakes.','original'),
('127.888.d.11.A',3,'A student runs a retractable gear through a swing test and checks the fluid level in the actuator. She is:','["painting the gear", "ignoring the gear", "inspecting and servicing landing gear such as fixed or retractable systems", "washing the plane"]'::jsonb,2,'Gear service.','original'),
('127.888.d.11.A',4,'A gear swing test is done with the aircraft on jacks so the gear can:','["break the jacks", "avoid inspection", "stay stuck", "retract and extend without bearing weight"]'::jsonb,3,'Swing test.','original'),
('127.888.d.11.B',3,'A mechanic places jacks at the specified jack points and raises the aircraft level before cycling the gear. She is:','["jacking an aircraft for a gear retraction check", "guessing the points", "lifting by the prop", "skipping jack points"]'::jsonb,0,'Jacking.','original'),
('127.888.d.11.B',4,'Jack points are specified in the manual because lifting elsewhere can:','["strengthen the skin", "damage the structure", "improve balance", "speed lifting"]'::jsonb,1,'Use jack points.','original'),
('127.888.d.11.C',3,'A technician checks wheel bearings for roughness, brake discs for wear and tire tread for cuts. She is:','["painting the wheel", "skipping checks", "inspecting wheels, brakes, bearings and tires", "washing the plane"]'::jsonb,2,'Wheel inspection.','original'),
('127.888.d.11.C',4,'A wheel bearing that feels rough when spun should be:','["reused", "ignored", "painted", "cleaned, inspected and replaced if damaged"]'::jsonb,3,'Bearing check.','original'),
('127.888.d.11.D',3,'A mechanic pumps the pedal and opens the bleeder screw until no bubbles come out of the brake line. She is:','["bleeding air from a hydraulic brake system", "adding air", "painting lines", "draining fuel"]'::jsonb,0,'Brake bleeding.','original'),
('127.888.d.11.D',4,'Air in a hydraulic brake line makes the pedal feel:','["hot", "spongy", "firm", "heavy"]'::jsonb,1,'Spongy pedal.','original'),
('127.888.d.11.E',3,'A student runs a gloved hand and a flashlight around a tire, looking for cuts, bulges and flat spots. She is:','["painting the tire", "adding tread", "inspecting a tire for defects", "buying a tire"]'::jsonb,2,'Tire inspection.','original'),
('127.888.d.11.E',4,'A bulge in a tire sidewall means the tire should be:','["over-inflated", "ignored", "painted", "removed from service"]'::jsonb,3,'Bulge means replace.','original'),
('127.888.d.11.F',3,'A mechanic bleeds off the strut''s pressure, removes the old valve and installs a new one. She is:','["replacing a shock strut air valve", "replacing a seat", "replacing a tire", "replacing a window"]'::jsonb,0,'Air valve.','original'),
('127.888.d.11.F',4,'Before removing a strut air valve, a mechanic must first:','["skip the step", "relieve the air pressure in the strut", "add more pressure", "heat the valve"]'::jsonb,1,'Relieve pressure.','original'),
('127.888.d.11.G',3,'A mechanic uses a manual to find the toe-in and camber specifications for the main gear. She is:','["guessing alignment", "painting the gear", "locating and explaining the process for checking landing gear alignment", "ignoring wheels"]'::jsonb,2,'Gear alignment.','original'),
('127.888.d.11.G',4,'Misaligned landing gear can cause:','["even wear", "less drag", "better handling", "uneven tire wear and poor handling"]'::jsonb,3,'Alignment effects.','original'),
('127.888.d.11.H',3,'A pilot reports a nose wheel that vibrates at taxi speed. The mechanic checks the shimmy damper, the wheel balance and loose nose gear parts. She is:','["troubleshooting a steering problem such as nose-wheel shimmy", "adding weight", "painting the nose wheel", "ignoring the report"]'::jsonb,0,'Shimmy.','original'),
('127.888.d.11.H',4,'A worn shimmy damper or loose torque links can cause:','["better steering", "nose wheel shimmy", "no vibration", "a smoother ride"]'::jsonb,1,'Shimmy causes.','original'),
('127.888.d.11.I',3,'A student identifies the gear position switches, indicator lights and warning horn on a diagram. She is:','["identifying seats", "identifying engines", "identifying landing gear position and warning system components", "identifying tires"]'::jsonb,2,'Gear indication parts.','original'),
('127.888.d.11.I',4,'A gear position switch tells the indicator system:','["the fuel level", "the pilot''s name", "the tire size", "whether the gear is up, down or in transit"]'::jsonb,3,'Gear switch.','original'),
('127.888.d.11.J',3,'The gear-down light stays dark even though the gear is down. The mechanic tests the bulb, the wiring and the switch. She is:','["troubleshooting a landing gear position and warning system", "painting the light", "ignoring the report", "replacing the tires"]'::jsonb,0,'Gear light fault.','original'),
('127.888.d.11.J',4,'A good first step in troubleshooting a gear indicator that fails is to:','["replace the gear", "check the bulb and the circuit breaker", "repaint the cover", "ignore the circuit"]'::jsonb,1,'Start simple.','original'),
('127.888.d.11.K',3,'A mechanic measures the brake lining against the wear limit and checks for leaks around the caliper. She is:','["washing a tire", "adding air", "inspecting a brake for serviceability", "painting a drum"]'::jsonb,2,'Brake serviceability.','original'),
('127.888.d.11.K',4,'Glazed, oil-soaked brake linings should be:','["polished", "left in place", "painted", "replaced and the leak source fixed"]'::jsonb,3,'Contaminated linings.','original'),
('127.888.d.11.L',3,'A student looks for bent tubes, cracks near welds and corrosion on the legs of a tube-type gear. She is:','["inspecting tube landing gear for damage", "ignoring the gear", "painting only", "washing the gear"]'::jsonb,0,'Tube gear check.','original'),
('127.888.d.11.L',4,'A crack near a weld on a landing gear leg should lead to:','["a bigger tire", "removal from service and evaluation or repair per the manual", "ignoring it", "a coat of paint"]'::jsonb,1,'Cracked gear.','original'),
('127.888.d.12.A',3,'A student labels a diagram with a reservoir, filter, flexible hose, rigid line, pump and accumulator. She is:','["describing fuel only", "describing pneumatic only", "describing hydraulic system components", "describing oxygen only"]'::jsonb,2,'Hydraulic parts.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_138'
from (values
('127.888.d.12.A',4,'The component that stores fluid for a hydraulic system is the:','["filter", "actuator", "accumulator", "reservoir"]'::jsonb,3,'Reservoir.','original'),
('127.888.d.12.B',3,'A mechanic explains that the filter traps particles, the pump creates flow and the accumulator smooths pressure surges. She is:','["explaining the function of hydraulic system components", "naming tires", "naming engines", "avoiding explanation"]'::jsonb,0,'Component functions.','original'),
('127.888.d.12.B',4,'An accumulator in a hydraulic system helps by:','["filtering air", "storing pressure and smoothing surges", "driving the prop", "cooling fuel"]'::jsonb,1,'Accumulator.','original'),
('127.888.d.12.C',3,'A technician follows a checklist to inspect, operate, service and troubleshoot the landing gear hydraulic system. She is:','["ignoring the system", "guessing", "explaining hydraulic system operation, inspections, operational checks, servicing and troubleshooting", "painting the system"]'::jsonb,2,'Hydraulic ops.','original'),
('127.888.d.12.C',4,'A hydraulic system that loses fluid without an external leak may have:','["a clean filter", "too much air", "a cold cabin", "an internal leak, such as a worn seal"]'::jsonb,3,'Internal leak.','original'),
('127.888.d.12.D',3,'A student names the air compressor, air bottle, regulator, moisture trap and air lines in a pneumatic system. She is:','["describing pneumatic system components", "describing seats", "describing hydraulic only", "describing engines"]'::jsonb,0,'Pneumatic parts.','original'),
('127.888.d.12.D',4,'A moisture separator in a pneumatic system is used to:','["add heat", "remove water from the compressed air", "add oil", "add water"]'::jsonb,1,'Moisture trap.','original'),
('127.888.d.12.E',3,'A mechanic explains that a regulator keeps air pressure at a steady level for the actuators. She is:','["describing fuel", "avoiding the topic", "explaining the function of pneumatic system components", "naming tires"]'::jsonb,2,'Pneumatic functions.','original'),
('127.888.d.12.E',4,'A check valve in an air line allows flow:','["only when hot", "both ways", "no way", "in one direction only"]'::jsonb,3,'Check valve.','original'),
('127.888.d.12.F',3,'A technician checks air bottle pressure, drains moisture and tests the emergency gear blow-down. She is:','["explaining pneumatic system operation, inspections, operational checks and servicing", "washing the plane", "skipping checks", "painting the bottle"]'::jsonb,0,'Pneumatic ops.','original'),
('127.888.d.12.F',4,'Pneumatic systems use air or nitrogen, so a leak will typically show as a:','["bright color", "hissing sound or pressure drop", "fluid puddle", "fuel smell"]'::jsonb,1,'Air leak signs.','original'),
('127.888.d.12.G',3,'A mechanic sorts seals made of rubber, neoprene and Teflon and checks which fluid each can handle. She is:','["ignoring fluids", "painting seals", "identifying types of hydraulic seals and fluid compatibility", "avoiding seals"]'::jsonb,2,'Seal compatibility.','original'),
('127.888.d.12.G',4,'A seal made for mineral oil fluid can fail quickly if used with:','["no fluid", "clean air", "fresh water", "phosphate-ester (Skydrol) fluid"]'::jsonb,3,'Wrong seal swells.','original'),
('127.888.d.12.H',3,'A student reads that a burst high-pressure line can throw fluid or gas with great force. She is researching:','["the risks associated with high-pressure gases and fluids", "no risks", "tire brands", "paint choices"]'::jsonb,0,'High-pressure risk.','original'),
('127.888.d.12.H',4,'Compressed gas bottles are dangerous because a damaged valve can:','["fill the shop with light", "turn the bottle into a projectile", "cool the shop", "clean the shop"]'::jsonb,1,'Bottle hazard.','original'),
('127.888.d.12.I',3,'A student researches what could happen if a technician opens a fitting before relieving the system pressure. She is identifying:','["tire risks", "paint risks", "the risks of not relieving system pressure before maintenance", "no risks"]'::jsonb,2,'Relieve pressure first.','original'),
('127.888.d.12.I',4,'Opening a line that still holds pressure may result in:','["a cooler system", "a cleaner line", "a faster repair", "fluid spray and injury"]'::jsonb,3,'Spray hazard.','original'),
('127.888.d.12.J',3,'A student researches the risks of leaving fluid in open cans or near ignition sources. She is identifying:','["the risks associated with storage and handling of hydraulic fluids", "tire brands", "paint choices", "no risks"]'::jsonb,0,'Fluid handling.','original'),
('127.888.d.12.J',4,'Some hydraulic fluids can irritate skin and eyes, so handlers should wear:','["sandals", "gloves and eye protection", "nothing", "a hat only"]'::jsonb,1,'PPE for fluid.','original'),
('127.888.d.12.K',3,'A mechanic is reminded that mixing two different fluid types in one system can ruin the seals. She is researching:','["engine noise", "tire wear", "the risks of cross-contamination of hydraulic fluids", "no risks"]'::jsonb,2,'Cross-contamination.','original'),
('127.888.d.12.K',4,'Adding the wrong type of fluid to a hydraulic reservoir can cause:','["a cleaner system", "better pressure", "longer life", "seal damage and system failure"]'::jsonb,3,'Wrong fluid.','original'),
('127.888.d.13.A',3,'A mechanic compares mineral-based, synthetic and phosphate-ester hydraulic fluids on a chart. She is:','["identifying different types of hydraulic fluids", "painting fluids", "mixing fluids", "avoiding fluids"]'::jsonb,0,'Fluid types.','original'),
('127.888.d.13.A',4,'Mineral-based hydraulic fluids are usually dyed:','["clear", "red", "white", "black"]'::jsonb,1,'Mineral fluid color.','original'),
('127.888.d.13.B',3,'A mechanic lubricates the seal, slides it into the groove and installs the backup ring on the pressure-free side. She is:','["cutting a hose", "removing a tire", "installing seals and backup rings in a hydraulic component", "painting a part"]'::jsonb,2,'Install seals.','original'),
('127.888.d.13.B',4,'A new seal should be lubricated with:','["dry grit", "any oil", "paint thinner", "clean hydraulic fluid of the system type"]'::jsonb,3,'Lube the seal.','original'),
('127.888.d.13.C',3,'A student removes a hydraulic filter element, cleans the bowl and replaces the element with a new gasket. She is:','["removing, cleaning, inspecting and installing a hydraulic filter", "adding fluid", "painting the filter", "ignoring the filter"]'::jsonb,0,'Filter service.','original'),
('127.888.d.13.C',4,'When a filter element is replaced, the old one should be:','["painted", "inspected for metal particles", "thrown away unseen", "reused"]'::jsonb,1,'Inspect old filter.','original'),
('127.888.d.13.D',3,'A mechanic checks the level on the sight glass, adds the correct fluid and tightens the cap. She is:','["cleaning tires", "draining fuel", "servicing a hydraulic system reservoir", "adding air"]'::jsonb,2,'Reservoir service.','original'),
('127.888.d.13.D',4,'A reservoir should be filled to the proper level because overfilling can:','["lower pressure", "cool the system", "improve flow", "cause fluid to overflow when it expands"]'::jsonb,3,'Overfill.','original'),
('127.888.d.13.E',3,'A mechanic operates the system and bleeds each line until the fluid shows no air bubbles. She is:','["purging air from a hydraulic system", "painting lines", "removing fuel", "adding air"]'::jsonb,0,'Purge air.','original'),
('127.888.d.13.E',4,'Air trapped in a hydraulic system can cause:','["perfect operation", "spongy or erratic operation", "cooler fluid", "faster pumping"]'::jsonb,1,'Air effects.','original'),
('127.888.d.13.F',3,'A technician checks fittings, hoses and actuators for wetness and checks air lines for hissing. She is:','["painting hoses", "adding fluid", "inspecting hydraulic and pneumatic systems for leaks", "avoiding the systems"]'::jsonb,2,'Leak inspection.','original'),
('127.888.d.13.F',4,'A hydraulic leak is often found by looking for:','["clean areas", "bright lights", "dry paint", "wet spots, stains and fluid residue"]'::jsonb,3,'Leak signs.','original'),
('127.888.d.13.G',3,'After finding a seep, the mechanic cleans the area, runs the system and traces the wet spot to its source. She is:','["troubleshooting hydraulic and pneumatic systems for leaks", "adding more fluid", "ignoring the seep", "painting the leak"]'::jsonb,0,'Trace leaks.','original'),
('127.888.d.13.G',4,'Cleaning a suspected leak area before testing helps the mechanic to:','["add pressure", "see where fresh fluid is coming from", "remove the system", "hide the leak"]'::jsonb,1,'Clean then test.','original'),
('127.888.d.13.H',3,'A mechanic opens the maintenance manual and finds the fluid type, fill level and servicing steps for the gear system. She is:','["using memory", "guessing fluid", "locating and explaining hydraulic fluid servicing instructions", "ignoring steps"]'::jsonb,2,'Fluid servicing data.','original'),
('127.888.d.13.H',4,'Hydraulic servicing instructions should be taken from:','["a flyer", "a radio ad", "a rumor", "the aircraft maintenance manual"]'::jsonb,3,'Use the AMM.','original'),
('127.888.d.13.I',3,'A technician matches a particular aircraft to the fluid listed on its reservoir placard and in the manual. She is:','["identifying and selecting hydraulic fluid for a given aircraft", "guessing fluid", "using any fluid", "using water"]'::jsonb,0,'Select fluid.','original'),
('127.888.d.13.I',4,'The type of hydraulic fluid for an aircraft is often listed:','["on the seat", "on a placard near the reservoir", "in the engine", "on the tail"]'::jsonb,1,'Fluid placard.','original'),
('127.888.d.13.J',3,'A mechanic finds the section in the manual that shows how to install a seal, backup ring or gasket in the right order. She is:','["avoiding procedures", "guessing", "locating installation procedures for a seal, backup ring or gasket", "using slang"]'::jsonb,2,'Seal procedures.','original'),
('127.888.d.13.J',4,'Following the exact installation procedure for a backup ring helps prevent:','["better sealing", "cleaner fluid", "longer life", "extrusion of the seal under pressure"]'::jsonb,3,'Backup ring.','original'),
('127.888.d.14.A',3,'A student explains how bleed air from the engine heats a cabin and pressurizes it. She is:','["explaining the operation and purpose of pressurization systems and bleed air heating", "explaining fuel", "avoiding heating", "explaining tires"]'::jsonb,0,'Bleed air.','original'),
('127.888.d.14.A',4,'Bleed air for cabin use is usually taken from the:','["landing gear", "engine compressor section", "fuel tank", "tail cone"]'::jsonb,1,'Bleed source.','original'),
('127.888.d.14.B',3,'A technician compares cooling gyros with forced air and cooling avionics with fans and ducts. She is:','["describing seats", "ignoring cooling", "explaining and comparing aircraft instrument cooling methods", "describing tires"]'::jsonb,2,'Instrument cooling.','original'),
('127.888.d.14.B',4,'Avionics need cooling mainly because heat can:','["improve them", "strengthen them", "clean them", "damage electronic components"]'::jsonb,3,'Heat risk.','original'),
('127.888.d.14.C',3,'A mechanic compares heat from engine exhaust passing through a muff with heat from a fuel-burning heater. She is:','["differentiating between exhaust heat exchanger and combustion heater systems", "comparing seats", "comparing lights", "comparing tires"]'::jsonb,0,'Heater types.','original'),
